  "driving routes and nearby openstreetmap listings via geoapify are requested for a trip when configured. place listings do not verify facilities or current availability.": {
    en: "Driving routes and nearby OpenStreetMap listings via Geoapify are requested for a trip when configured. Place listings do not verify facilities or current availability.",
    es: "Las rutas de conducción y listados de OpenStreetMap mediante Geoapify se solicitan cuando están configuradas. Los listados no verifican instalaciones ni disponibilidad actual.",
    fr: "Les itinéraires et points d'intérêt OpenStreetMap via Geoapify sont récupérés selon la configuration. Les listes ne garantissent pas les équipements ni la disponibilité.",
    de: "Fahrrouten und nahegelegene OpenStreetMap-Einträge via Geoapify werden geladen. Einträge überprüfen weder Einrichtungen noch die aktuelle Verfügbarkeit.",
    ja: "設定時、Geoapifyを介してOpenStreetMapの走行ルートや周辺スポットを取得します。施設内容やリアルタイムの営業状況を保証するものではありません。",
    hi: "कॉन्फ़िगर होने पर Geoapify के माध्यम से ड्राइविंग मार्ग और पास के OpenStreetMap सूचियों का अनुरोध किया जाता है। लिस्टिंग सुविधाओं या वर्तमान उपलब्धता की पुष्टि नहीं करती हैं।",
    zh: "根据系统配置，驾车路线与沿途兴趣点数据由 Geoapify / OpenStreetMap 实时计算。地图标点不构成对设施现状或营业时段的绝对保证。",
    ar: "يتم طلب مسارات القيادة وقوائم OpenStreetMap القريبة عبر Geoapify عند تكوينها. لا تؤكد القوائم توفر المرافق حاليًا.",
    it: "I percorsi di guida e i punti OpenStreetMap via Geoapify vengono caricati se configurati. Gli elenchi non verificano servizi o disponibilità attuale.",
    pt: "Rotas de condução e locais do OpenStreetMap via Geoapify são obtidos quando configurados. As listagens não verificam instalações ou disponibilidade atual.",
  },
