  "ensure your vehicle is equipped with a spare tyre, jack, first-aid kit, emergency water, and physical cash for remote stretch toll booths or petrol pumps where upi/card networks may experience cell tower outage.": {
    en: "Ensure your vehicle is equipped with a spare tyre, jack, first-aid kit, emergency water, and physical cash for remote stretch toll booths or petrol pumps where UPI/card networks may experience cell tower outage.",
    es: "Asegúrese de llevar rueda de repuesto, gato, botiquín, agua potable y efectivo para peajes o gasolineras en zonas remotas donde la señal de red móvil falle.",
    fr: "Assurez-vous d'avoir une roue de secours, un cric, une trousse de secours, de l'eau et des espèces pour les péages ou stations isolées sans réseau.",
    de: "Führen Sie Ersatzreifen, Wagenheber, Erste-Hilfe-Kasten, Notwasser und Bargeld mit für entlegene Mautstellen oder Tankstellen ohne Mobilfunkempfang.",
    ja: "携帯電波が届かない人里離れた料金所やガソリンスタンドに備え、スペアタイヤ、ジャッキ、救急箱、飲料水、現金を必ず車内に常備してください。",
    hi: "सुनिश्चित करें कि आपका वाहन अतिरिक्त टायर, जैक, प्राथमिक चिकित्सा किट, आपातकालीन पानी और टोल बूथ या पेट्रोल पंपों के लिए नकद से सुसज्जित है जहां नेटवर्क आउटेज हो सकता है।",
    zh: "长途远行前务必确认车内配备备胎、千斤顶、急救包及应急饮用水，并备好现金，以防偏远公路加油站或收费站遭遇基站信号盲区无法刷卡扫码。",
    ar: "تأكد من تزويد سيارتك بإطار احتياطي ورافعة وحقيبة إسعافات أولية ومياه طوارئ ونقود ورقية لمحطات الوقود في المناطق النائية التي قد ينقطع فيها الاتصال.",
    it: "Assicurati che il veicolo sia dotato di ruota di scorta, cric, kit di pronto soccorso, acqua e contanti per le zone remote prive di copertura di rete.",
    pt: "Certifique-se de que seu veículo possui pneu sobressalente, macaco, kit de primeiros socorros, água e dinheiro para pedágios ou postos em áreas sem sinal.",
  },
