  "travel durations are based on standard road conditions and posted speed limits. actual drive times may fluctuate significantly due to seasonal monsoon landslides, construction detours, religious processions, or holiday weekend toll plaza congestion.": {
    en: "Travel durations are based on standard road conditions and posted speed limits. Actual drive times may fluctuate significantly due to seasonal monsoon landslides, construction detours, religious processions, or holiday weekend toll plaza congestion.",
    es: "Las duraciones se basan en condiciones estándar y límites de velocidad. Los tiempos reales pueden variar por obras, procesiones, atascos de fin de semana o lluvias.",
    fr: "Les durées de trajet sont basées sur des conditions normales et les limites de vitesse. Le temps réel peut varier en cas de travaux, météo ou embouteillages.",
    de: "Fahrtzeiten basieren auf normalen Straßenverhältnissen und Tempolimits. Tatsächliche Zeiten können durch Baustellen, Unwetter oder Feiertagsverkehr variieren.",
    ja: "移動時間は標準的な道路状況と制限速度に基づいて算出されています。モンスーンの雨、工事による迂回、祝日の渋滞などにより変動する場合があります。",
    hi: "यात्रा की अवधि मानक सड़क स्थितियों और गति सीमाओं पर आधारित है। मौसम, निर्माण, त्योहारों या सप्ताहांत टोल भीड़ के कारण वास्तविक समय भिन्न हो सकता है।",
    zh: "行车预估时间基于通常路况与法定限速计算。遇季风暴雨、修路改道、民俗集会或节假日收费站排队拥堵，实际耗时可能有较大波动。",
    ar: "تعتمد أوقات السفر على ظروف الطرق العادية والسرعات المحددة. قد تختلف أوقات القيادة الفعلية بسبب الأمطار أو أعمال البناء أو ازدحام العطلات.",
    it: "I tempi di viaggio si basano su condizioni normali e limiti di velocità. I tempi reali possono variare a causa di maltempo, lavori o traffico nei festivi.",
    pt: "A duração da viagem é baseada em condições normais e limites de velocidade. O tempo real pode variar devido a obras, clima ou trânsito em feriados.",
  },
