    de: "Der Server-Geoapify-API-Schlüssel ist nicht konfiguriert. Setzen Sie GEOAPIFY_API_KEY in Vercel.",
    ja: "サーバーのGeoapify APIキーが設定されていません。Vercelの本番環境でGEOAPIFY_API_KEYを設定してください。",
    hi: "सर्वर Geoapify API कुंजी कॉन्फ़िगर नहीं है। Vercel में GEOAPIFY_API_KEY सेट करें।",
