  "tripverse balances daily travel times, stay dates, and activities for a seamless, realistic itinerary.": {
    en: "TripVerse balances daily travel times, stay dates, and activities for a seamless, realistic itinerary.",
    es: "TripVerse equilibra los tiempos de viaje, estadías y actividades para un itinerario realista.",
    fr: "TripVerse équilibre les temps de trajet, l'hébergement et les activités pour un itinéraire fluide et réaliste.",
    de: "TripVerse balanciert Reisezeiten, Aufenthalte und Aktivitäten für eine realistische Reiseroute.",
    ja: "TripVerseは移動時間、宿泊日程、アクティビティをバランスよく調整し、現実的で快適な旅程を作成します。",
    hi: "TripVerse सहज, यथार्थवादी यात्रा कार्यक्रम के लिए दैनिक यात्रा समय, ठहरने की तारीखों और गतिविधियों को संतुलित करता है।",
    zh: "TripVerse综合权衡每日行程耗时、住宿日期和游玩项目，打造平滑顺畅、合理可行的旅程。",
    ar: "يوازن TripVerse بين أوقات السفر اليومية وتواريخ الإقامة والأنشطة للحصول على خط سير واقعي وسلس.",
    it: "TripVerse bilancia tempi di viaggio, alloggi e attività per un itinerario armonioso e realistico.",
    pt: "O TripVerse equilibra tempos diários de viagem, estadias e atividades para um roteiro realista e fluido.",
  },
  "tripverse is free to use and does not have live accommodation inventory. search the destination on a booking provider, then confirm the property, availability, safety, price, and cancellation terms there. booking and payment happen directly with that provider.": {
    en: "TripVerse is free to use and does not have live accommodation inventory. Search the destination on a booking provider, then confirm the property, availability, safety, price, and cancellation terms there. Booking and payment happen directly with that provider.",
    es: "TripVerse es de uso gratuito y no cuenta con inventario de alojamiento en vivo. Busque el destino en un proveedor y confirme disponibilidad, precio y condiciones allí.",
    fr: "TripVerse est gratuit et ne possède pas d'inventaire d'hébergement en direct. Recherchez la destination sur un site de réservation et confirmez les conditions directement là-bas.",
    de: "TripVerse ist kostenlos und verfügt über kein eigenes Unterkunfts-Inventar. Suchen Sie das Reiseziel auf Buchungsportalen und prüfen Sie Verfügbarkeit und Preise direkt dort.",
    ja: "TripVerseは無料で利用でき、自社での宿泊施設在庫は保持していません。提携予約サイトで空室状況、料金、キャンセル規約をご確認のうえ直接ご予約ください。",
    hi: "TripVerse मुफ़्त है और इसमें लाइव आवास सूची नहीं है। बुकिंग प्रदाता पर गंतव्य खोजें, फिर सीधे वहीं संपत्ति, उपलब्धता, सुरक्षा और कीमत की पुष्टि करें।",
    zh: "TripVerse供免费使用，并不直接持有实时房源库存。请在预订平台上搜索目的地，并在该平台上确认房型、房量、安全性、价格和取消政策。预订及支付均在提供商处完成。",
    ar: "استخدام TripVerse مجاني ولا يحتوي على مخزون إقامة مباشر. ابحث عن الوجهة لدى مزود الحجز، ثم أكد الحجز والدفع مباشرة مع ذلك المزود.",
    it: "TripVerse è gratuito e non dispone di inventario di alloggi in tempo reale. Cerca la struttura su un portale di prenotazione e conferma disponibilità e prezzi direttamente lì.",
    pt: "O TripVerse é gratuito e não possui inventário de acomodações ao vivo. Pesquise o destino em um provedor de reservas e confirme preços e termos diretamente com ele.",
  },
  "tripverse matches live google flights, irctc express trains, redbus volvo coaches, and zoomcar self-drives with direct booking deep-links.": {
    en: "TripVerse matches live Google Flights, IRCTC Express trains, redBus volvo coaches, and Zoomcar self-drives with direct booking deep-links.",
    es: "TripVerse empareja vuelos de Google, trenes IRCTC, autobuses redBus y alquileres de Zoomcar con enlaces directos.",
    fr: "TripVerse intègre Google Flights, trains IRCTC, bus redBus et locations Zoomcar avec liens directs.",
    de: "TripVerse verknüpft Live-Google Flights, IRCTC-Züge, redBus-Busse und Zoomcar-Mietwagen mit Direktlinks.",
    ja: "TripVerseはGoogleフライト、IRCTC列車、redBus高速バス、Zoomcarレンタカーと連携し直接予約リンクを提供します。",
    hi: "TripVerse सीधे बुकिंग डीप-लिंक के साथ Google Flights, IRCTC एक्सप्रेस ट्रेनों, redBus वोल्वो कोचों और Zoomcar सेल्फ-ड्राइव का मिलान करता है।",
    zh: "TripVerse与Google航班、IRCTC特快列车、redBus豪华客车及Zoomcar自驾直达预订深度链接精准匹配。",
    ar: "يربط TripVerse بين رحلات Google Flights وقطارات IRCTC وحافلات redBus مع روابط حجز مباشرة.",
    it: "TripVerse abbina voli Google Flights, treni IRCTC, pullman redBus e auto a noleggio Zoomcar con link diretti.",
    pt: "O TripVerse combina voos do Google Flights, trens IRCTC, ônibus redBus e carros Zoomcar com links diretos.",
  },
  "tripverse matches real, verified hotels and boutique stays with instant booking.com & google hotels booking links.": {
    en: "TripVerse matches real, verified hotels and boutique stays with instant Booking.com & Google Hotels booking links.",
    es: "TripVerse empareja hoteles verificados con enlaces directos a Booking.com y Google Hotels.",
    fr: "TripVerse sélectionne des hôtels vérifiés avec liens directs Booking.com et Google Hotels.",
    de: "TripVerse vermittelt echte, verifizierte Hotels mit direkten Buchungslinks zu Booking.com und Google Hotels.",
    ja: "TripVerseはBooking.comやGoogle Hotelsの直接予約リンク付きで、検証済みのホテルやブティック宿泊施設を提案します。",
    hi: "TripVerse त्वरित Booking.com और Google Hotels बुकिंग लिंक के साथ वास्तविक, सत्यापित होटलों का मिलान करता है।",
    zh: "TripVerse提供真实经过验证的酒店与精品民宿，并配有Booking.com与Google Hotels即时预订链接。",
    ar: "يطابق TripVerse الفنادق الحقيقية والمعتمدة مع روابط حجز فورية على Booking.com وGoogle Hotels.",
    it: "TripVerse abbina hotel reali e verificati con link di prenotazione istantanea su Booking.com e Google Hotels.",
    pt: "O TripVerse combina hotéis reais e verificados com links instantâneos para o Booking.com e Google Hotels.",
  },
